-- ============================================
-- LUMA — Thème 17 : MOYEN 3/3 x4 — Regarder un match dans un pub sportif
-- ============================================


update scenarios set content = '{"characters": {"bartender": "le barman", "stranger": "un inconnu supporter"}, "start_node": "n1", "nodes": {"n1": {"speaker": "bartender", "text": "Big match tonight! What can I get you while we wait for kickoff?", "text_fr": "Gros match ce soir ! Je vous sers quoi en attendant le coup d''envoi ?", "choices": [{"text": "A pint of your local draft, please.", "text_fr": "Une pinte de votre bière pression locale, s''il vous plaît.", "next": "n2"}, {"text": "Just a soda for now, I''m driving later.", "text_fr": "Juste un soda pour l''instant, je conduis plus tard.", "next": "n2b"}]}, "n2": {"speaker": "bartender", "text": "Good choice, that one pairs well with match night energy.", "text_fr": "Bon choix, celle-là va bien avec l''énergie d''une soirée match.", "choices": [{"text": "Perfect, I''m ready for this game.", "text_fr": "Parfait, je suis prêt pour ce match.", "next": "n3"}]}, "n2b": {"speaker": "bartender", "text": "Smart, this place gets rowdy during big games!", "text_fr": "Intelligent, cet endroit devient bruyant pendant les gros matchs !", "choices": [{"text": "Ha, I can already feel the energy building.", "text_fr": "Ha, je peux déjà sentir l''énergie monter.", "next": "n3"}]}, "n3": {"speaker": "stranger", "text": "Mind if I grab this seat? Every other spot''s taken tonight.", "text_fr": "Ça vous dérange si je prends cette place ? Toutes les autres sont prises ce soir.", "choices": [{"text": "Not at all, plenty of room. Who are you rooting for?", "text_fr": "Pas du tout, y''a de la place. Vous supportez qui ?", "next": "n4"}, {"text": "Sure, go ahead! This place really fills up for big matches.", "text_fr": "Bien sûr, allez-y ! Cet endroit se remplit vraiment pour les gros matchs.", "next": "n4"}]}, "n4": {"speaker": "stranger", "text": "Been a fan since I was a kid, honestly. This rivalry means everything to me.", "text_fr": "Fan depuis que je suis gamin, honnêtement. Cette rivalité représente tout pour moi.", "choices": [{"text": "That''s awesome, I can already tell tonight''s going to be intense.", "text_fr": "C''est génial, je peux déjà dire que ce soir va être intense.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(The match kicks off, and the whole pub erupts with every close call.)", "text_fr": "(Le match commence, et tout le pub explose à chaque occasion manquée.)", "choices": [{"text": "(Cheer along with the crowd during an exciting play.)", "text_fr": "(Acclame avec la foule pendant une action excitante.)", "next": "n6"}]}, "n6": {"speaker": "stranger", "text": "(After a goal) YES! Did you see that shot?! Incredible!", "text_fr": "(Après un but) OUI ! T''as vu ce tir ?! Incroyable !", "choices": [{"text": "That was amazing! This atmosphere is honestly electric.", "text_fr": "C''était incroyable ! Cette ambiance est vraiment électrique.", "next": "n7"}]}, "n7": {"speaker": "stranger", "text": "This is exactly why I love watching matches here instead of alone at home.", "text_fr": "C''est exactement pour ça que j''adore regarder les matchs ici plutôt que seul chez moi.", "choices": [{"text": "I completely agree, the shared excitement makes it so much better.", "text_fr": "Je suis totalement d''accord, l''excitation partagée rend ça bien meilleur.", "next": "n8"}]}, "n8": {"speaker": "bartender", "text": "(As the match ends) Great game tonight, wasn''t it?", "text_fr": "(Alors que le match se termine) Beau match ce soir, non ?", "choices": [{"text": "Absolutely, this was such a fun night. Thanks for the recommendations!", "text_fr": "Absolument, c''était une soirée si fun. Merci pour les recommandations !", "next": "end_watched"}]}, "end_watched": {"speaker": "stranger", "text": "Come back next match, this seat''s yours anytime!", "text_fr": "Reviens au prochain match, cette place est à toi n''importe quand !", "end": true, "ending_label": "Soirée match au pub, ambiance électrique 🍺⚽🎉"}}}'::jsonb, is_playable = true
where title = 'Regarder un match dans un pub sportif'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
